        "| ፲፫ ወአምድጎረ ለፉ አሉ ናሁ መልአክ አግዚአብሔር || አስተርአዮ በሕልም ለዮለፍ አንዘ ይብል ተን || | ሥእክ ወንሣእ ሕፃነ ወእሞ ወገጕያይ ውስተ ብሔረ | ግብፅ ወሀሉ ህየ አስክ አመ እነግረክ አስመ ሀለዎ | ለሄሮድስ ይሣሥ ለሕፃን ከመ ይቅትሉሎ።",
