    (2, 8, "h | {ደቋ ቃል በራማ ተሰምፀ ብካይ ወሰቆቃው ወገዓር ወሕ aa i a i የኢተዮጵያ ኦርተዶክስ ተዋሐዶ ቤተ a ወንቴል ዛማቴቲዎበ ፪።"),
