    (2, 15, "ክፍል $፡ በኣንተ ስብከተ ዮሐንስ መጥምቁ።"),
    (2, 16, "| ዕይ ወበውአቱ መቁዋዕል በጽሐ ዮሐንስ መጥምቅ ኣንዘ ይሰብክ በገዳመ ይሁዳ ዘዮርዳኖስ = | hክ | ዩ ኣንዛ ይብል ነስሑ እስመ ቀርበት መንግሥተ ሰማ ያት።"),
    (2, 17, "| {ር ኣስመ ዝንቱ ውእቱ ዘተብህለ በኢሳይያስ ነቢይ ኣንዛ ይብል ቃለ ንዋዲ ዘይሰብክ በገዳም ወይብል | ጺሑአ ፍኖቶ ለአግዚአብሔር ወርቱዕዐ ግበሩ መጽ | ያሕቶ።"),
