    (3, 5, "| ሐ | A 11 ወናሁ መጽአ ቃል አምሰማይ ዘይብል ዝንቱ ውእ [| እ ቱ ወልድየ ዘአፈቅር ዘቦቱ ሠመርኩ።"),
