    (5, 44, "| ቑ አላ ዝግቡ ለክሙ መዝገበ ዘበሰማያት ኃበ ኢይብሊ | ወኢይማስን ወኢያማስናኖ ፃፄ ወቍንሑቍኔ ወሣበ ሰረ || ) ቅት ኢይክከርዬዩ ወል. ይሰርቅያዎ።"),
