    (5, 46, "| ፪፪ ማኅቶቱ ለሥጋክ ፀይንከ ውእቱ እምከመ ፀይንክ | . ብፍህ ወስፉሕ ውእቱ ዙሉ ሥጋከ ብሩሃ ይከውን።"),
