    (6, 10, "| ብዩ ክስመ ዘንተሰ ኵሎ አሕዛበ ዓለም ዝዘአፍኣ የኃሥ | | ሥዎ ወለክሙስሰ የአምር አቡክሙ ሰማያዊ ከመ | | ትፈቅዱ ዘንተ ዙሎ።"),
