        15,
        33,
        "| | | ፳ጀ ወበቁዊኦአ ውስተ ቤት አቅደመ አግዚኣ ኢየሱስ ብሂ | ወ; ሎቶ ምንተ ትብል » ስምያን ነገሥተ ምድር አም [| ዎን} ኀበ መኑ ይነሥኡ ጸባሕተ ወጋዳ እምኀበ ውሉ | ን | ሙኑ ወሚመ እምሣበ ነኪር?።",
