    (15, 35, "| | ፱ ወበይአቲ ሰዓት ቀርቡ ኀቤሁ አርዳአ.ሁ ለኣግዚአ || በዞ ኢየሱስ እንዘ ይብሉ መኑ አንጋ የዓቢ በመንግሥተ | በ።"),
