        15,
        36,
        "C, ዩ ወጸውዐ ሕፃነ ወአቀሞ ማአክሎሙ = [wy የ ወይቤ አማን እብለክሙ አመ ኢተመየጥክሙ ወኢ. | ht ከንክሙ ከመ ዝንቱ ሕፃን አትበውኡ ውስተ መን | ከ ግሥተ ሰማያት።",
