    (16, 3, "l | ፲፫ ወኣምከመ ረክበ አማን እብለክሙ ከመ ይትፌሣሕ || በአንቲአሁ ፈድፋደ እምተስዓ ወተስዓቱ እለ ኢተ || | ገድፉ።"),
    (16, 4, "| | {8 ከማሁኬ ኢይፈቀድ አቡየኒ ዘበሰማያት ከመ ይትኀጎ |[ | ጐል አሐዱ አምክአሉ ንኡሳን።"),
