    (16, 6, "lf ፲፮ ወእመሰ ኣኢሰምዖሙ ሎሙሂ ንግራ ለቤተ ክርስቲ || ያ), ወእመሰ ለቤተ ክርስቲያንሂ ኢሰምዓ ይኩን ከ | መ አረማዊ ወመጸብሐቁ።"),
    (16, 7, "| {፳ኛ አማን ኣብለክከሙ ዘአሠርክሙ በምድር ይከውን ኣ [ | ሱረ በሰማያት ፡ ወዘፈታሕክሙ በምድር ይከውን || ፍቱሐ በሰማያት።"),
    (16, 8, "| | ፲፱ ወዓዲ እብለክሙ ለእመ ኀብሩ ክልኤቱ አው ሠለ | ስቱ እምኔክሙ በውስተ ምድር በእንተ ዙሉ ግብር || | ዘሰጸሉ ይትገበር ሎሙ በኀበ አቡየ ዘበሰማያት።"),
