    (22, 42, "| ሣ፫ ወዛንተ በሕቱ አእምሩ ዕበሁ የአምር በዓለ ቤት || ጊዜ ይመጽኣ ሰራቁ አምተግህ ወአምሐለወ ወአ | ምኢጎደን ይክርዩ ቤቶ።"),
    (
        22,
        43,
        "| ጓፀ ከማሁ አንትሙሂ ድልዋኒክወሖ ሀልዉ አስመ በጊዜ || ኢትሐዘብክሙ ይመጽ» ወልደ ኦጓለ አመሕያው = | | ጓደ መኑ አንጋ ገብር ምአሙን ወጠመቢ.ብ ዘይሠይሞ አግ | ዘኩ ውስተ ዙሉ ቤቱ ከመ የሀቦሙ ሲሳዮሙ በጊዜሁ = | ዕኔ ብፁዕ ውኣቱ ገብር ዘመጸ.ኦ አግዘኡ ይረክቦ ኣንዛ ዘንተ ይገብር።",
    ),
    (22, 44, "ጓፄ አሣን አብለክሙ ከመ ዲበ ዙሉ ንዋዩ ይሠይሞ = | ሳጓ ወአመሰ ይቤ ውኣአቱ ገብር አኩይ በልቡ ይጐነዲ | አቲወ አግዚክአዩ።"),
    (22, 45, "| ሳዓ፱ ወይዛብጥ አብያጺሁ አግብርተ ወይበልዕ ወይሰቲ ምስለ ሰካርያን።"),
    (22, 46, "| ዛዛ ወይመጽእኣ አግዚኡ ለውአቱ ገብር በዕለተ ኢተሐ | ዘበ ወበጊዜ ኢያእመረ ወይስጥቁ አማኣከሉ።"),
    (23, 1, "yh ወይሬሲ መክፈል ምስለ መደልዋን ግበ ሀሎ | ብካይ ወሐቅየ ስነን።"),
    (
        23,
        2,
        "| | [ 5 አሜሃ ትመስል መንግሥተ ሰማያት ፀሥሮን ደና | | ግለ እለ ነሥአ መጋኃትዊሆን ወወጽኣ ለቀበላ | | መርዓዊ = | | ዩ ወኃምስ አምውስቱቶን ዐፀብዳት እማንቱ ፡ ወኃምስ ጠበባት።",
    ),
    (23, 3, "| | | የ ወዐብዳትዕሰ ነሚጾአን መኃትዊሆን ኢነሥክአ ቁብክ | ምስሌሆን = . 8 ወጠበባትሰ ነሥአ ቅብአ በገማዕዊሆን ምስለ መጋ ትፍዊሆን።"),
    (23, 4, "ደ ወጐንድዮ መርዓዊ ደቀሳ ዙሎን ወኖማ።"),
    (23, 5, "| ሄ ወከዊኖ መንፈቀ ሌሲት ውውዓ ክነ ናሁ መርዓዊ | መጽእ ፡ ፃኡ ውስተ ቀበላሁ።"),
    (
        23,
        6,
        "| ፮2 ወእምዝ ነቅሓ እልኩ ደናግል ሹኵሎን ወኣሠነያ መኃትዊሆን ወመጽኣ ለቀበላ መርዓዊ = ቋቋ ወእልኩ አብዳ ይቤላሆን ለጠባባት ሀበነ ቅብፀ ኣም ቅብዕክን ኣስመ መኃትቁዊነ ጠፍኣነ = ዘ ወአውሥአኣሆን ጠበባት ወይቤላሆን አልቦ ዘየ አክል ለነ ወለክን ፡ አላ ሑራ እምኀበ አለ ይሠይጡ ወተሣየጣ ፅክን።",
    ),
    (23, 7, "የኢችዮጵጽያ አርቶዯፉክስ ተዋሐዶ ቤተ ፳፪ ወንኔል ዘማቲታስ ሸጀ።"),
    (23, 8, '- - ፲{ ወሐዊሮን ይሣየጣ በጽሐ መርዳዊ ወቦአ ምስሌሁ | አልኩ እለ ድልዋት ውስተ ከብካብ ፡ ወተፀጽወ ፲8 "ኖግት።'),
    (23, 9, "ወድግረ መጽኣ አልክቱሂ ደናግል ወይቤላ አግዚኦ።"),
    (
        23,
        10,
        "አግዚኦ አርጎወነ = | ፲፪ ወአውሥአን ወይቤሎን አማን እብለክን ከመ ኢየ አምረን እስመ ስአንክን ተጊሃ ወአም ስዮ ምስሌየ = ፲፫ ትግሁኬ አስመ ኢተአምሩ ዕለታ ወሰዓታ እንተ በቲ ይመጽእ ወልዶ አጓለ አመሕያው።",
    ),
    (23, 11, "ክፍል ቫወ ፡ ምሳሌ በአንተ መክልይ።"),
    (23, 12, "| ፲8 አስመ ክመ ብአሲ ዘይነግድ ወጸውፀ አግብርቲሁ ወወሀበሙ ንዋዮ ይትገበሩ በቱ።"),
    (
        23,
        13,
        "፲፪ ቦ ለዛወሀቦ ኀምስተ መክሊተ ፡ ወበ ለዛወህቦ ክል ኤተ መክሊተ ፡ ወቦ ለዛወሀቦ አሐደ መክሊተ ፣ | ወለለ አሐዱ አምኔሆሙ በአምጣነ ይክሉ ወሀቦሙ | | ወነገደ በጊዜሃ።",
    ),
    (
        23,
        14,
        "| ፲፮ ወሖረ ዝኩ ዘኃምሰ መክልየ ነሥአ ወተገበረ ቦቶን | ወረብኃ ክልአተ ኃምስተ መክልየ = ፲፮ ወከማሁ ዘሂ ክልኤተ መክልየ ነሥአ ረብኃ ክልአተ || | ክልኤተ መካልየ።",
    ),
    (
        23,
        15,
        "| | ፲፳ ወዘኣሐተሰ መክሊተ ነሥክ ሐረ ወከረየ ምድረ ወጎ | | ብክ ወርቀ እግዚኡ = | | ፲፱ ወአምድግረ ብዙግ መዋዕል አተወ እግዚኦሙ ለእሉ | አግብርት ወአሣዛ ይትሐሰበሙ።",
    ),
    (
        23,
        16,
        "| ጽ ወቀርበ ዘጎምፅሰ መክልየ ነሥአ ወአምጽአ ክልአተ || ኃምሰ መክልየ እንዛ ይብል ኣአከኑ ክግዚአ ኃምስ | vy መክልየ ወሀብከኒ ወናሁ ኃምስ መክልይ እክለ ረባ || | ኅዅዙ ዲቤሆን።",
    ),
    (23, 17, "| | ጽክ ወይቤሎ አግሂዚኡ ፡ ኦአ ገብር ጌር ወምኣአመን ዘበው | ተድ ምሕአመነ ከንከ ዲበ ብዙሣ እሠይመክከ ባኣ | ውስተ ፍሥሓሁ ለእግዚእክ።"),
    (
        23,
        18,
        "| ቋቛ8ፀ ወመጽአ ዘክልኤተ መክሊተ ነሥአ '፡ ወይቤ እግዚኦ» አኮሁ ክልኤተ መክከልየ ወሀብከኒ ፡ ወናሁ ካልአተ ክልኤተ መክልየ አለ ረባኀኩ ዲቤሆን = ጀየ ወይቤሰ አግዚኡ ኦ ገብር ጌቴር ወም አመን ዘበው ተድ ምእመነ ከንክ ዲበ ብዙኃ እሠይመክ በእ ውስተ ፍሥሓሁ ለአግዚእአክ = | ሸ፱ ወመጽአ ዘአሐተኒ መክሊተ ነሥአ ወይቤ አግዚኦ | አአምረክ ከመ ድሩክ ብእሲ አንተ ፡ ተአርር አምኀበ || ኢዘራእክ ወታስተጋብክ አምኀኻበ ኢዛዘረውክ = ሸሯ ወፈሪህየ ሖርኩ ወከረይኩ ምድረ ወጎበኣአኩ መክ ሊተከ ውስተ ምድር ናሁ እንከ መክሊተከ።",
    ),
    (23, 19, "ጽ2 ወአውሥአ አግዚኡ ወይቤሎ ኦ ገብር ሀክይ ወኣኩይድ ተአምረኒኑ ከመ ብኣሲ ድሩክ ኣነ አአርር አምጎበ | ኢዛራእwሙ ወኣስተ ጋብእ አምኀበ እዛረውኩ።"),
    (
        23,
        20,
        "| rr rr yr የኢጥዮጵያ ኦርዯፉክስ ተዋሐዶ ቤተ h - ወንጌል ዘማቴዎስ ፳፪ = ጽሂ እምደለወከ ታግብ» ወርቅየ ውስተ ማኣድየ ወመ | [i ጺኣየ አምአክስተገበርክዎ ለልየ በርዴ።",
    ),
    (
        23,
        21,
        "| ኢ | ጅሯ ወይቤሎሙ ለእለ ይቀውሙ ህየ ንሥኡ እምኔሁ | ከ | ዘንተ መክሊተ ወሀብዎ ለዛቦቱ ዐሠርቱ መክሊት = | ሲ ቛ፱ ክስመ ለዘቦ ይሁብዎ ወይዌስክዎ፡ ወለዛስ አልቦ ላ አለሂ በ የሀይድዎ ፡ | bp ቋ ወለገብርሰ አኩይ ወህክይ አውጽአዎ አፍአ ወደይዎ | ክ | ውስተ ጾናፌ ጽልመት ኀበ ሀሎ ብካይ ወሐቅየ ስነን።",
    ),
    (
        23,
        22,
        "ስ ከፍል ወፀ , በእንተ ምጽአቱ ለክርዕቶስ = | ቁይ ወአመ ይመጽኣ ወኳይ አጓለ ኣመሕያው በስብሐ | የ ቲሁ ወዙሎሙ መላእክቲሁ ቅዱሳን ምስሌሁ ፣ || በ አሜሃ ይነብር ዲበ መንበረ ስብሐቲሁ = | P ብዩ ወይትጋብኡ ሹኵሎሙ አሕዛብ ቅድሜሁ ወይፈል || አ ጠሙ ዘዘዚአሆሙ ከመ እንተ ይፈልጥ ዛላዊ አስበ | ሱ ግበ አምአጣሊ።",
    ),
    (23, 23, "ር የ ወያቀውም አበግፀቦ በየማኑ ወአጣሌ በጸጋሙ።"),
    (23, 24, "NW ቋ8 አሜሃ ይብሎሙ ንጉሥ ለኣለ በየማኑ ፡ ንሁ ኀቤየ [| ያ ቡሩክኑ ለኣቡየ ትረሱ መንግሥተ ሰማያት ዘድልው | U ለክሙ ኣምቅድመ ይትፈጠር ዓለም።"),
