    (25, 6, "2 ወተንሥአ ሊቀ ካህናት ወይቤሎ ኢትሰጠውኑ እንዘ | መጠነዝ ያስተዋድዩክ።"),
    (25, 7, "| ቋር ወኢያውሥኦአ ኣአግዚእአ ኢየሱስ ፡ ወይቤሎ ለ.ቀ ካህ | ናት አምሐልኩክ በአግዛ አብሔር ሕያው ክመ ትን | ግረኒ እመ አንተሁ ክርስቶስ ወልዱ ለአግሂኣብሔር።"),
